def split_reduction_traffic_ratio(p, hw, cfg) -> float:
    """Extra DRAM bytes the split-K reduction moves (serial: sk-1 read+write fix-ups of the accumulator-type output; parallel: sk partials written and read back), relative to compulsory A+B+C bytes. 0 at split_k=1. Larger is worse."""
    if cfg.split_k <= 1:
        return 0.0
    part = p.M * p.N * p.acc_bytes_per_element
    extra = 2.0 * (cfg.split_k - 1) * part if cfg.split_k_mode == "serial" else 2.0 * cfg.split_k * part
    base = (p.M * p.K + p.K * p.N + p.M * p.N) * p.bytes_per_element
    return extra / max(1.0, base)
